TLM.f("Sancti/08-14",{"officium":"In Vigilia Assumptionis B.M.V.","rule":["no Gloria","Prefatio=Communis","Suffragium=Spiritu;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 44:13; 44:15; 44:16"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: adducéntur Regi Vírgines post eam: próximæ ejus adducéntur tibi in lætítia et exsultatióne."}],"Oratio":[{"k":"text","la":"Deus, qui virginálem aulam beátæ Maríæ, in qua habitáres, elígere dignátus es: da, quǽsumus; ut, sua nos defensióne munitos, jucúndos fácias suæ interésse festivitáti:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:23-31"},{"k":"text","la":"Ego quasi vitis fructificávi suavitátem odóris: et flores mei fructus honóris et honestátis. Ego mater pulchræ dilectiónis, et timóris, et agnitiónis, et sanctæ spei. In me grátia omnis viæ et veritátis: in me omnis spes vitæ et virtútis. Transíte ad me, omnes, qui concupíscitis me, et a generatiónibus meis implémini. Spíritus enim meus super mel dulcis, et heréditas mea super mel et favum. Memória mea in generatiónes sæculórum. Qui edunt me, adhuc esúrient: et qui bibunt me, adhuc sítient. Qui audit me, non confundétur: et qui operántur in me, non peccábunt. Qui elúcidant me, vitam ætérnam habébunt."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 11:27-28"},{"k":"text","la":"In illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud."}],"Offertorium":[{"k":"text","la":"Beáta es, Virgo María, quæ ómnium portásti Creatórem: genuísti qui te fecit, et in ætérnum pérmanes Virgo."}],"Secreta":[{"k":"text","la":"Múnera nostra, Dómine, apud cleméntiam tuam Dei Genetrícis comméndet orátio: quam idcírco de præsénti sǽculo transtulísti; ut pro peccátis nostris apud te fiduciáliter intercédat."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Concéde, miséricors Deus, fragilitáti nostræ præsídium: ut, qui sanctæ Dei Genetrícis festivitátem prævenímus; intercessiónis ejus auxílio a nostris iniquitátibus resurgámus."},{"k":"macro","name":"Per eundem"}]},"hr":{"92898c593a318cb8":{"t":"Ps 44, 13 i 15 i 16, Ps 44, 2\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 13 et 15 et 16) Za pogledom tvojeg lica vapit će svi velikani. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti i veselju."},"8ce1eb73b22bd1cc":{"t":"<i>Pomolimo se</i>.\nBože, koji si djevičansko krilo blažene Marije odabrao da se u njemu nastaniš; zaštiti nas, molimo te, njezinom obranom i daj nam da radosno doživimo njezinu svetkovinu.\n<i>Koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si iza, brao djevičansko krilo blaižene Marije, da se u njemu nastaniš, po, daj, molimo, da pomoću njezine zaštite radosni prisustvujemo njezinoj svatkovini, koji živiš i kralj.uješ .","knRef":"Kniewald 1942, str. 678–679 (snimka 340) (OCR)"},"2de5fba36a04c0be":{"t":"Sir 24, 23-31\nČitanje knjige Mudrosti. Ja sam kao loza dala ugodan miris, a cvijeće moje rod je slavan i častan. Ja sam majka lijepe ljubavi, straha, znanja i svetoga ufanja. U meni je sva milina življenja i istine, u meni je sva nada života i kreposti. Dođite k meni svi koji me želite i nasitite se plodova mojih. Jer je duh moj slađi od meda i nasljedstvo je moje slađe od medenoga saća. Uspomena je moja trajna kroz naraštaje. Koji mene blaguju još će gladovati i koji mene piju još će žeđati. Tko mene sluša neće se postidjeti, i koji rade po meni neće griješiti. Koji mene slave imat će život vječni."},"d55bb9f2100a7850":{"t":"Blagoslovljena si i časna, Djevo Marijo, koja si bez povrede djevičanstva bila majka Spasiteljeva. Bogorodice Djevo, u tvojem se zatvori krilu i posta čovjek onaj koga sav svijet ne može obuhvatiti.","kn":", Blagcislovema si i časna. Djevo Marlj'O, koja se bez povrede čistoće nađe mati Spasiteljeva. Bogorodice Djevo u tvojem se, postavši čovj.ek, zatvori krilu, koga sav svijet ne obuhvata.","knRef":"Kniewald 1942, str. 700–701 (snimka 351) (OCR)"},"d34dc2adfd4e4049":{"t":"Lk 11, 27-28\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Kad je Isus govorio narodu, reče mu glasno neka žena iz naroda: Blago tijelu koje te je nosilo i prsima koja su te dojila. On na to odgovori: Još više blago onima koji slušaju Božju riječ i drže je.","kn":"t Slijedi sveto evanđelje po Luki (11, 27-28). U ono vrijeme, kad je Isus govorio narodu, reče mu glasno neka žena iz naroda: Blago tijelu, koje te je. nosilo i prsima, koja su te dojila. On na to Odgovori: Još više blago onima, koji slušaju Božju riječ i drže je.","knRef":"Kniewald 1942, str. 638–639 (snimka 320) (OCR)"},"6356ff1e5bf54d76":{"t":"Blažena si, Djevice Marijo, koja si nosila Stvoritelja svega; porodila si onoga koji te je stvorio i dovijeka ostaješ Djevica.","v":"aleluia → ∅","kn":"Blažena si, Djevice Marijo, koja si nosila Stvoritelja svega, rodila si onoga, koji je Tebe stvorioi 1 dovijeka ostaješ djevicom.","knRef":"Kniewald 1942, str. 678–679 (snimka 340) (OCR)"},"b0fb49ec85eedc92":{"t":"Neka naše darove tvojoj dobroti, Gospodine, preporuči molitva Bogorodice, koju si zato premjestio s ovoga svijeta da kod tebe nas grješnike pouzdano zagovara.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Preporučila Tvojoj blagosti, Gospodline, naše darove molitva Bogorodičina, koju si zato prenio s ovoga svijeta, da nas radi naših grijeha pouzdano zagovara kod Tebe, po G. n.","knRef":"Kniewald 1942, str. 678–679 (snimka 340) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"4cc414b9b992a40d":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca.","kn":"Blaženokrilo Djevice Marije, koje je nosilo Sina vječnoga Oca,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"a2c572783f73f924":{"t":"<i>Pomolimo se</i>.\nPodaj milosrdni Bože, zaštitu našoj slaboći, da mi koji pretječemo svetkovinu svete Bogorodice, uz pomoć njezina zagovora uskrsnemo od naših bezakonja.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, milosrdni Bože, natoj slabosti ovu potporu, da mi, koji pretječemo svetkovinu svete Bogorodice, pomoću njezina zagovora ustanemo od naših zloća, po istom G. n.","knRef":"Kniewald 1942, str. 678–679 (snimka 340) (OCR)"}}});
